contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking an amount to forward to c.go
    function run(uint amount) public payable {
        // If we will send Ether, ensure the test contract has it
        require(address(this).balance >= amount);

        // observe owner before
        address ownerBefore = c.owner();
        // observe balances before
        uint cBalBefore = address(c).balance;
        uint myBalBefore = address(this).balance;

        bool reverted;
        // perform the state-changing call as its own top-level statement
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe owner and balances after
        address ownerAfter = c.owner();
        uint cBalAfter = address(c).balance;
        uint myBalAfter = address(this).balance;

        // General rule asserted for all inputs: owner never changes; if call succeeded then C's balance is zero and this test's balance did not increase (no Ether leaked to caller)
        assert(ownerBefore == ownerAfter && (reverted || (cBalAfter == 0 && myBalAfter <= myBalBefore)));
    }

    // allow receiving Ether if target forwards to us during execution
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    receive() external payable { }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // record balances and owner before
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        address beforeOwner = c.owner();

        bool reverted;
        // call go with value = amount
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        address afterOwner = c.owner();

        // General rule: if call did not revert then c.balance decreased by exactly amount
        // and this contract's balance did not increase (owner may have been paid externally).
        assert(reverted || (beforeC >= afterC && beforeC - afterC == amount && afterThis <= beforeThis && afterOwner == beforeOwner));
    }
}
